<?php
require __DIR__.'/lib.php';need_admin();
$all=db_read('content');$news=array_values(array_filter($all,fn($r)=>($r['type']??'')==='berita'));$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_check();$id=(string)($_POST['id']??'');$ix=null;foreach($all as $i=>$r)if(($r['id']??'')===$id && ($r['type']??'')==='berita'){$ix=$i;break;}
 if($ix===null){$notice='Berita tidak ditemukan.';}
 else {
  $gallery=array_values(array_filter($all[$ix]['images']??[],'is_string'));if(!$gallery&&!empty($all[$ix]['image']))$gallery=[$all[$ix]['image']];
  if(($_POST['operation']??'')==='remove'){$target=(string)($_POST['target']??'');$gallery=array_values(array_filter($gallery,fn($v)=>$v!==$target));}
  elseif(($_POST['operation']??'')==='add'){
   $f=$_FILES['photo']??null;if(!$f||($f['error']??4)!==UPLOAD_ERR_OK||($f['size']??0)>4*1024*1024||count($gallery)>=5){$notice='Pilih foto yang valid dan pastikan tidak lebih dari 5 foto.';}
   else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)$notice='Format foto tidak didukung.';else{$dir=__DIR__.'/assets/images';if(!is_dir($dir))mkdir($dir,0755,true);$name='assets/images/berita-'.bin2hex(random_bytes(15)).'.'.$ext;if(move_uploaded_file($f['tmp_name'],__DIR__.'/'.$name))$gallery[]=$name;else $notice='Foto belum berhasil disimpan.';}}
   }
  if(!$notice){$all[$ix]['images']=$gallery;$all[$ix]['image']=$gallery[0]??'';$notice=db_write('content',$all)?'Galeri berita berhasil diperbarui.':'Perubahan belum dapat disimpan.';}
 }
 $news=array_values(array_filter($all,fn($r)=>($r['type']??'')==='berita'));
}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Galeri Berita Cikoko</title><style>body{margin:0;background:#f3f7fb;font:14px system-ui,sans-serif;color:#17365a}header{background:#12365c;color:#fff;padding:18px}header a{color:white}main{max-width:1080px;margin:20px auto;padding:0 14px}.card{background:white;border:1px solid #dce5ef;padding:18px;border-radius:12px;margin-bottom:14px}.gallery{display:flex;gap:8px;overflow:auto}.gallery img{width:145px;height:115px;object-fit:cover;border-radius:8px}button{padding:10px 14px;border-radius:8px;border:0;background:#246ad4;color:#fff;cursor:pointer}input{margin:6px}h1{font-size:23px}.notice{padding:12px;background:#e2effc;border-radius:10px}</style></head><body><header><b>Kelurahan Cikoko · Kelola Galeri Berita</b> · <a href="admin.php?type=berita">Kembali ke Berita</a></header><main><h1>Publikasi Berita — Hingga 5 Foto</h1><p>Foto pertama akan menjadi sampul. Foto yang lain muncul pada galeri geser di aplikasi.</p><?php if($notice):?><p class="notice"><?=esc($notice)?></p><?php endif;?><?php foreach($news as $r):$imgs=array_values(array_filter($r['images']??[],'is_string'));if(!$imgs&&!empty($r['image']))$imgs=[$r['image']];?><div class="card"><h2><?=esc($r['title'])?></h2><div class="gallery"><?php foreach($imgs as $image):?><div><img src="<?=esc(url($image))?>" alt="Foto berita"><form method="post"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="id" value="<?=esc($r['id'])?>"><input type="hidden" name="target" value="<?=esc($image)?>"><input type="hidden" name="operation" value="remove"><button>Hapus dari Galeri</button></form></div><?php endforeach;?></div><?php if(count($imgs)<5):?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=esc(csrf())?>"><input type="hidden" name="id" value="<?=esc($r['id'])?>"><input type="hidden" name="operation" value="add"><label>Tambahkan foto (<?=count($imgs)?>/5)</label><input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required><button>Unggah Foto</button></form><?php endif;?></div><?php endforeach;?></main></body></html>
